d7ce8e0b541735') OR (no_var=8710 AND MD5(nama)='5d820fcd9bfe5e681ec5d91f16755f40' AND data_type='data_sql' AND MD5(sql_query)='cefcc67d8ce1bf13dc3689ac89cb8eca'))), ' dari 6 (diubah orang sesudah dipasang? dibiarkan)')) AS hasil;
